import sys
def abs_diff(n1, n2, n3):
    nums = [n1, n2, n3]
    max_sum = sum(max(int(c) for c in str(n)) for n in nums)
    min_sum = sum(min(int(c) for c in str(n)) for n in nums)
    return abs(max_sum - min_sum)
if __name__ == "__main__":
    d = sys.stdin.read().split(); n1 = int(d[0]); n2 = int(d[1]); n3 = int(d[2])
    print(abs_diff(n1, n2, n3))

